def write_data(message):
    # 向命名管道写入数据
    try:
        with open('/tmp/mypipe1', 'w') as pipe:
            pipe.write(message + '\n')
            pipe.flush()  # 确保数据写入管道
            print(f"Message sent: {message}")
    except OSError as e:
        print("Error writing to pipe:", e)

