def update_chess_pieces_from_fen(fen):
    """
    根据FEN字符串更新棋子的位置和可见性
    """
    # 棋子位置定义（仅用作参考）
    positions = {
        'br1': (-500, -315), 'bn1': (-430, -315), 'bb1': (-360, -315),
        'ba1': (-290, -315), 'bk1': (-220, -315), 'ba2': (-150, -315),
        'bb2': (-80, -315), 'bn2': (-10, -315), 'br2': (60, -315),
        'bc1': (-430, -175), 'bc2': (-10, -175), 'bp1': (-500, -105),
        'bp2': (-354, -105), 'bp3': (-220, -105), 'bp4': (-80, -105),
        'bp5': (60, -105), 'rr1': (-500, 315), 'rn1': (-430, 315),
        'rb1': (-360, 315), 'ra1': (-290, 315), 'rk1': (-220, 315),
        'ra2': (-150, 315), 'rb2': (-80, 315), 'rn2': (-10, 315),
        'rr2': (60, 315), 'rc1': (-430, 175), 'rc2': (-10, 175),
        'rp1': (-500, 105), 'rp2': (-360, 105), 'rp3': (-220, 105),
        'rp4': (-80, 105), 'rp5': (60, 105)
    }

    # 将所有棋子设置为隐藏
    for piece in positions:
        SetFlag(globals()[f'ui_' + piece], lv.obj.FLAG.HIDDEN, True)

    # FEN字符到棋子类型的映射
    fen_to_piece = {
        'r': 'br', 'n': 'bn', 'b': 'bb', 'a': 'ba', 'k': 'bk', 'c': 'bc', 'p': 'bp',
        'R': 'rr', 'N': 'rn', 'B': 'rb', 'A': 'ra', 'K': 'rk', 'C': 'rc', 'P': 'rp'
    }

    # 记录每种棋子的使用情况
    piece_count = {k: 1 for k in fen_to_piece.values()}

    # 棋盘格子的大小
    grid_width = 70
    grid_height = 70

    # 拆分FEN字符串并获取棋子和spinner位置
    fen_parts = fen.split(' ', 1)  # 限制split只分割第一个空格
    fen_rows = fen_parts[0].split('/')

    # 确保我们有足够的部分来提取spinner位置
    if len(fen_parts) > 1:
        spinner_positions = fen_parts[1].strip()  # 提取spinner位置
    else:
        spinner_positions = ""

    # 输出调试信息
    print(f"FEN parts: {fen_parts}")
    print(f"Spinner positions: {spinner_positions}")

    # 映射FEN字符串到棋盘
    for y, row in enumerate(fen_rows):
        x = 0
        for char in row:
            if char.isdigit():
                x += int(char)  # 空格
            else:
                piece = fen_to_piece[char]
                piece_number = piece_count[piece]
                piece_name = f'{piece}{piece_number}'
                piece_count[piece] += 1

                if piece_name in positions:
                    ui_piece = globals()[f'ui_{piece_name}']
                    SetFlag(ui_piece, lv.obj.FLAG.HIDDEN, False)
                    SetFlag(ui_piece, lv.obj.FLAG.SCROLLABLE, False)
                    # 使用正确的格子大小计算棋子位置
                    ui_piece.set_x(-500 + x * grid_width)
                    ui_piece.set_y(-315 + y * grid_height)
                x += 1

    # 更新spinner位置
    if len(spinner_positions) == 4:
        # 解析spinner位置
        spinner1_row = int(spinner_positions[0])  # Use as-is
        spinner1_col = int(spinner_positions[1])  # Use as-is
        spinner3_row = int(spinner_positions[2])  # Use as-is
        spinner3_col = int(spinner_positions[3])  # Use as-is

        print(f"Parsed Spinner1 position: Row {spinner1_row}, Col {spinner1_col}")
        print(f"Parsed Spinner3 position: Row {spinner3_row}, Col {spinner3_col}")

        # spinner1位置计算
        ui_Spinner1.set_x(-500 + spinner1_col * grid_width)
        ui_Spinner1.set_y(-315 + spinner1_row * grid_height)

        # spinner3位置计算
        ui_Spinner3.set_x(-500 + spinner3_col * grid_width)
        ui_Spinner3.set_y(-315 + spinner3_row * grid_height)

    else:
        print("Spinner positions are not correctly formatted or missing.")

    # 载入界面
    lv.scr_load(ui_Screen1)

